SELECT t1.ACCT_NAME AS "Account Name",PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY CAST(t0.price * 2 AS DOUBLE PRECISION) ASC) AS "Percentile Expression" FROM trading.trades AS t0 LEFT OUTER JOIN ref_data.account_master AS t1 ON (t1.ID = t0.account_id AND t1.in_z <= '2030-01-01 00:00:00' AND (t1.out_z > '2030-01-01 00:00:00' OR t1.out_z IS NULL)) WHERE t0.in_z <= '2030-01-01 00:00:00' AND (t0.out_z > '2030-01-01 00:00:00' OR t0.out_z IS NULL) GROUP BY t1.ACCT_NAME ORDER BY t1.ACCT_NAME ASC NULLS FIRST
